    }
}

static void at_exit_cleanup(void)
{
    if (st.screen)
        delscreen(st.screen);
    free(st.ttypath);
}

static void refresh_time(void)
{
    char buf[128];
    int hour;

    st.now = time(NULL);
    st.tm = localtime(&st.now);
    if (st.opt.utc)
        st.tm = gmtime(&st.now);

    hour = st.tm->tm_hour;
    if (st.opt.twelve)
        st.suffix = (hour >= 12) ? pm_suffix : am_suffix;
    else
        st.suffix = "";

    if (st.opt.twelve && hour > 12)
        hour -= 12;
    if (st.opt.twelve && hour == 0)
        hour = 12;

    st.hh[0] = hour / 10;
    st.hh[1] = hour % 10;
    st.mm[0] = st.tm->tm_min / 10;
    st.mm[1] = st.tm->tm_min % 10;

    strcpy(st.prev_datestr, st.datestr);
    strftime(buf, sizeof(buf), st.opt.fmt, st.tm);
    sprintf(st.datestr, "%s%s", buf, st.suffix);

    st.ss[0] = st.tm->tm_sec / 10;
    st.ss[1] = st.tm->tm_sec % 10;
}

static void paint_digit(int digit, int row, int col)
{
    int k;
    int c = col;

    for (k = 0; k < 30; ++k, ++c) {
        if (c == col + 6) {
            c = col;
            ++row;
        }
        if (st.opt.bold)
            wattron(st.clockwin, A_BLINK);
        else
            wattroff(st.clockwin, A_BLINK);
        wbkgdset(st.clockwin, COLOR_PAIR(glyphs[digit][k / 2]));
        mvwaddch(st.clockwin, row, c, ' ');
    }
    wrefresh(st.clockwin);
}

static void paint(void)
{
    chtype sep;

    if (st.opt.show_date && !st.opt.bounce &&
        strcmp(st.datestr, st.prev_datestr) != 0)
        move_clock(st.geo.row, st.geo.col, st.geo.width, st.geo.height);

    paint_digit(st.hh[0], 1, 1);
    paint_digit(st.hh[1], 1, 8);

    sep = COLOR_PAIR(1);
    if (st.opt.blink && time(NULL) % 2 == 0)
        sep = COLOR_PAIR(2);

    wbkgdset(st.clockwin, sep);
    mvwaddstr(st.clockwin, 2, 16, "  ");
    mvwaddstr(st.clockwin, 4, 16, "  ");

    paint_digit(st.mm[0], 1, 20);
    paint_digit(st.mm[1], 1, 27);

    if (st.opt.bold)
        wattron(st.datewin, A_BOLD);
    else
        wattroff(st.datewin, A_BOLD);

    if (st.opt.show_date) {
        wbkgdset(st.datewin, COLOR_PAIR(2));
        mvwprintw(st.datewin, DATE_H / 2, 1, st.datestr);
        wrefresh(st.datewin);
    }

    if (st.opt.seconds) {
        wbkgdset(st.clockwin, sep);
        mvwaddstr(st.clockwin, 2, CLOCK_W_SHORT, "  ");
        mvwaddstr(st.clockwin, 4, CLOCK_W_SHORT, "  ");
        paint_digit(st.ss[0], 1, 39);
        paint_digit(st.ss[1], 1, 46);
    }
}

static void move_clock(int row, int col, int width, int height)
{
    /* wipe the old position */
    wbkgdset(st.clockwin, COLOR_PAIR(0));
    wborder(st.clockwin, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
    werase(st.clockwin);
    wrefresh(st.clockwin);

    if (st.opt.show_date) {
        wbkgdset(st.datewin, COLOR_PAIR(0));
        wborder(st.datewin, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
        werase(st.datewin);
        wrefresh(st.datewin);
    }

    st.geo.row = row;
    st.geo.col = col;
    mvwin(st.clockwin, st.geo.row, st.geo.col);
    st.geo.height = height;
    st.geo.width = width;
    wresize(st.clockwin, st.geo.height, st.geo.width);

    if (st.opt.show_date) {
        mvwin(st.datewin,
              st.geo.row + st.geo.height - 1,
              st.geo.col + (st.geo.width / 2) - (strlen(st.datestr) / 2) - 1);
        wresize(st.datewin, DATE_H, strlen(st.datestr) + 2);
        if (st.opt.framed)
            box(st.datewin, 0, 0);
    }

    if (st.opt.framed)
        box(st.clockwin, 0, 0);

    wrefresh(st.clockwin);
    wrefresh(st.datewin);
}

static void bounce_step(void)
{
    if (!st.opt.bounce)
        return;

    if (st.geo.row < 1)
        st.geo.drow = 1;
    if (st.geo.row > (LINES - st.geo.height - DATE_H))
        st.geo.drow = -1;
    if (st.geo.col < 1)
        st.geo.dcol = 1;
    if (st.geo.col > (COLS - st.geo.width - 1))
        st.geo.dcol = -1;

    move_clock(st.geo.row + st.geo.drow, st.geo.col + st.geo.dcol,
               st.geo.width, st.geo.height);
}

static void toggle_seconds(void)
{
    int w, shift;

    st.opt.seconds = !st.opt.seconds;
    w = st.opt.seconds ? CLOCK_W_LONG : CLOCK_W_SHORT;

    for (shift = 0; (st.geo.col - shift) > (COLS - w - 1); ++shift)
        ;

    move_clock(st.geo.row, st.geo.col - shift, w, st.geo.height);
    set_centered(st.opt.centered);
}

static void set_centered(bool on)
{
    st.opt.centered = on;
    if (on) {
        st.opt.bounce = false;
        move_clock(LINES / 2 - (st.geo.height / 2),
                   COLS / 2 - (st.geo.width / 2),
                   st.geo.width, st.geo.height);
    }
}

static void set_framed(bool on)
{
    st.opt.framed = on;

    wbkgdset(st.clockwin, COLOR_PAIR(0));
    wbkgdset(st.datewin, COLOR_PAIR(0));

    if (on) {
        wbkgdset(st.clockwin, COLOR_PAIR(0));
        wbkgdset(st.datewin, COLOR_PAIR(0));
        box(st.clockwin, 0, 0);
        box(st.datewin, 0, 0);
    } else {
        wborder(st.clockwin, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
        wborder(st.datewin, ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ');
    }

    wrefresh(st.datewin);
    wrefresh(st.clockwin);
}

static void set_color(int c)
{
    st.opt.color = c;
    init_pair(1, st.bgcolor, c);
    init_pair(2, c, st.bgcolor);
}

static void handle_input(void)
{
    int ch;
    struct timespec wait = { st.opt.delay, st.opt.nsdelay };
    fd_set fds;

    FD_ZERO(&fds);
    FD_SET(STDIN_FILENO, &fds);

    if (st.opt.saver) {
        ch = wgetch(stdscr);
        if (ch != ERR && !st.opt.noquit) {
            st.alive = false;
        } else {
            nanosleep(&wait, NULL);
            if (ch >= '0' && ch <= '7')
                set_color(ch - '0');
        }
        return;
    }

    ch = wgetch(stdscr);
    switch (ch) {
    case KEY_RESIZE:
        endwin();
        setup();
        break;

    case KEY_UP:
    case 'k':
    case 'K':
        if (st.geo.row >= 1 && !st.opt.centered)
            move_clock(st.geo.row - 1, st.geo.col, st.geo.width, st.geo.height);
        break;

    case KEY_DOWN:
    case 'j':
    case 'J':
        if (st.geo.row <= (LINES - st.geo.height - DATE_H) && !st.opt.centered)
            move_clock(st.geo.row + 1, st.geo.col, st.geo.width, st.geo.height);
        break;

    case KEY_LEFT:
    case 'h':
    case 'H':
        if (st.geo.col >= 1 && !st.opt.centered)
            move_clock(st.geo.row, st.geo.col - 1, st.geo.width, st.geo.height);
        break;

    case KEY_RIGHT:
    case 'l':
    case 'L':
        if (st.geo.col <= (COLS - st.geo.width - 1) && !st.opt.centered)
            move_clock(st.geo.row, st.geo.col + 1, st.geo.width, st.geo.height);
        break;

    case 'q':
    case 'Q':
        if (!st.opt.noquit)
            st.alive = false;
        break;

    case 's':
    case 'S':
        toggle_seconds();
        break;

    case 't':
    case 'T':
        st.opt.twelve = !st.opt.twelve;
        refresh_time();
        move_clock(st.geo.row, st.geo.col, st.geo.width, st.geo.height);
        break;

    case 'c':
    case 'C':
        set_centered(!st.opt.centered);
        break;

    case 'b':
    case 'B':
        st.opt.bold = !st.opt.bold;
        break;

    case 'r':
    case 'R':
        st.opt.bounce = !st.opt.bounce;
        if (st.opt.bounce && st.opt.centered)
            st.opt.centered = false;
        break;

    case 'x':
    case 'X':
        set_framed(!st.opt.framed);
        break;

    case '0': case '1': case '2': case '3':
    case '4': case '5': case '6': case '7':
        set_color(ch - '0');
        break;

    default:
        pselect(1, &fds, NULL, NULL, &wait, NULL);
        break;
    }
}

static void setup(void)
{
    struct sigaction sa;

    setlocale(LC_TIME, "");

    st.bgcolor = COLOR_BLACK;

    if (st.ttypath) {
        FILE *fp = fopen(st.ttypath, "r+");
        if (!fp) {
            fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s.\n",
                    st.ttypath, strerror(errno));
            exit(EXIT_FAILURE);
        }
        st.screen = newterm(NULL, fp, fp);
        if (st.screen == NULL)
            __assert_fail("ttyclock.ttyscr != NULL", "ttyclock.c", 53, "init");
        set_term(st.screen);
    } else {
        initscr();
    }

    cbreak();
    noecho();
    keypad(stdscr, true);
    start_color();
    curs_set(false);
    clear();

    if (use_default_colors() == OK)
        st.bgcolor = -1;

    init_pair(0, st.bgcolor, st.bgcolor);
    init_pair(1, st.bgcolor, st.opt.color);
    init_pair(2, st.opt.color, st.bgcolor);
    refresh();

    sa.sa_handler = on_signal;
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGSEGV, &sa, NULL);

    st.alive = true;
    if (!st.geo.drow)
        st.geo.drow = 1;
    if (!st.geo.dcol)
        st.geo.dcol = 1;
    st.geo.width = st.opt.seconds ? CLOCK_W_LONG : CLOCK_W_SHORT;
    st.geo.height = CLOCK_H;
    refresh_time();

    st.clockwin = newwin(st.geo.height, st.geo.width, st.geo.row, st.geo.col);
    if (st.opt.framed)
        box(st.clockwin, 0, 0);

    if (st.opt.bold)
        wattron(st.clockwin, A_BLINK);

    st.datewin = newwin(DATE_H, strlen(st.datestr) + 2,
                        st.geo.row + st.geo.height - 1,
                        st.geo.col + (st.geo.width / 2) - (strlen(st.datestr) / 2) - 1);
    if (st.opt.framed && st.opt.show_date)
        box(st.datewin, 0, 0);
    clearok(st.datewin, true);

    set_centered(st.opt.centered);

    nodelay(stdscr, true);

    if (st.opt.show_date)
        wrefresh(st.datewin);

    wrefresh(st.clockwin);
}

static void usage(void)
{
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n"
           "    -s            Show seconds                                   \n"
           "    -S            Screensaver mode                               \n"
           "    -x            Show box                                       \n"
           "    -c            Set the clock at the center of the terminal    \n"
           "    -C [0-7]      Set the clock color                            \n"
           "    -b            Use bold colors                                \n"
           "    -t            Set the hour in 12h format                     \n"
           "    -u            Use UTC time                                   \n"
           "    -T tty        Display the clock on the specified terminal    \n"
           "    -r            Do rebound the clock                           \n"
           "    -f format     Set the date format                            \n"
           "    -n            Don't quit on keypress                         \n"
           "    -v            Show tty-clock version                         \n"
           "    -i            Show some info about tty-clock                 \n"
           "    -h            Show this page                                 \n"
           "    -D            Hide date                                      \n"
           "    -B            Enable blinking colon                          \n"
           "    -d delay      Set the delay between two redraws of the clock. Default 1s. \n"
           "    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

int main(int argc, char **argv)
{
    int opt;

    memset(&st, 0, sizeof(st));

    st.opt.show_date = true;
    strncpy(st.opt.fmt, "%F", sizeof(st.opt.fmt));
    st.opt.color = COLOR_GREEN;
    st.opt.delay = 1;
    st.opt.nsdelay = 0;
    st.opt.blink = false;

    atexit(at_exit_cleanup);

    while ((opt = getopt(argc, argv, "iuvsScbtrhBxnDC:f:d:T:a:")) != -1) {
        switch (opt) {
        case 'i':
            puts("TTY-Clock 2 \xc2\xa9 by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)");
            exit(EXIT_SUCCESS);
        case 'u':
            st.opt.utc = true;
            break;
        case 'v':
            puts("TTY-Clock 2 \xc2\xa9 devel version");
            exit(EXIT_SUCCESS);
        case 's':
            st.opt.seconds = true;
            break;
        case 'S':
            st.opt.saver = true;
            break;
        case 'c':
            st.opt.centered = true;
            break;
        case 'b':
            st.opt.bold = true;
            break;
        case 'C':
            if (atoi(optarg) >= 0 && atoi(optarg) < 8)
                st.opt.color = atoi(optarg);
            break;
        case 't':
            st.opt.twelve = true;
            break;
        case 'r':
            st.opt.bounce = true;
            break;
        case 'f':
            strncpy(st.opt.fmt, optarg, FMT_MAX);
            break;
        case 'd':
            if (atol(optarg) >= 0 && atol(optarg) < 100)
                st.opt.delay = atol(optarg);
            break;
        case 'D':
            st.opt.show_date = false;
            break;
        case 'B':
            st.opt.blink = true;
            break;
        case 'a':
            if (atol(optarg) >= 0 && atol(optarg) < 1000000000)
                st.opt.nsdelay = atol(optarg);
            break;
        case 'x':
            st.opt.framed = true;
            break;
        case 'T': {
            struct stat sb;
            if (stat(optarg, &sb) == -1) {
                fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n",
                        optarg, strerror(errno));
                exit(EXIT_FAILURE);
            } else if (!S_ISCHR(sb.st_mode)) {
                fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n",
                        optarg);
                exit(EXIT_FAILURE);
            } else {
                free(st.ttypath);
                st.ttypath = strdup(optarg);
            }
            break;
        }
        case 'n':
            st.opt.noquit = true;
            break;
        case 'h':
        default:
            usage();
            exit(EXIT_SUCCESS);
        }
    }

    setup();
    attron(A_BLINK);
    while (st.alive) {
        bounce_step();
        refresh_time();
        paint();
        handle_input();
    }

    endwin();
    return 0;
}
